 public record Sound(String getLocation){}public record Holder(Object value){}public record Step(Object getLevel,Object getSound,double x,double y,double z,float getNewVolume){public Object getPosition(){return new net.minecraft.world.phys.Vec3(x,y,z);}public boolean isCanceled(){return false;}}
 static Soldier npc(World w)throws Exception{var s=new Soldier(w);s.x=.5;s.y=10;s.z=.5;var t=new net.minecraft.nbt.CompoundTag();t.putInt("npc22_role",3);Roles22.read(s,t);Social.init(s);s.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND,new ItemStack("tacz:gun",1));return s;}
 public static void main(String[]a)throws Exception{var w=new World();var n=npc(w);w.now=100;TeamBrain.soundEvent(new Step(w,new Holder(new Sound("minecraft:block.stone.step")),5,10,.5,.15f));var listen=Sense28.state(n);ok(listen.heard==100&&listen.priority==1,"quiet footsteps enter bounded listening memory");ok(listen.x==5,"sound stores source position");ok(Sense28.tick(n),"idle NPC actively looks toward heard footsteps");ok(n.shift&&n.nav.stops>0,"inspection is crouched and pauses navigation");float yaw=n.getYHeadRot();w.now=101;Sense28.tick(n);ok(Math.abs(n.getYHeadRot()-yaw)<=5.01,"heard direction turn bounded to five degrees per tick");Sense28.hear(n,8,10,0,3,110);Sense28.hear(n,-8,10,0,1,125);ok(listen.x==8&&listen.priority==3,"footsteps cannot overwrite recent gunshot attention");long deadline=listen.end;Sense28.hear(n,9,10,0,3,130);ok(listen.end==deadline,"repeated equal noises do not restart an endless scanning animation");ok(Sense28.offset(20)==Sense28.offset(39)&&Sense28.offset(65)==Sense28.offset(85),"left and right inspection include real dwell intervals");ok(Sense28.delta(179,-179)==2,"turn across yaw wrap uses short direction");var target=new TacticsChecks24.Target(w);target.x=8;target.y=10;CalmBrain.state(n).target=target;ok(!Sense28.tick(n)&&!Sense28.active(n),"visible enemy immediately interrupts surroundings scan");CalmBrain.state(n).target=null;w.now=120;Sense28.STATES.clear();Sense28.EVENTS.clear();Sense28.sound(new Step(w,new Holder(new Sound("minecraft:weather.rain")),5,10,.5,1));ok(Sense28.STATES.isEmpty(),"weather ignored rather than triggering constant head motion");
 w.rayBlocked=true;ok(Sense28.corner(n,200),"new obstructed cell starts deliberate corner check");ok(Sense28.state(n).end==290,"inspection lasts four and a half seconds");Sense28.state(n).end=0;ok(!Sense28.corner(n,300),"same cell does not endlessly restart inspection");w.rayBlocked=false;
 // A three-high side wall provides a genuine stair support. Head clearance is excavated first.
 target.x=5;target.y=13;CalmBrain.state(n).target=target;for(int y=10;y<=12;y++)w.blocks.put(new BlockPos(1,y,0),"minecraft:stone");var eng=Field28.state(n);ok(Field28.plan(n,eng,400),"trapped NPC plans a single local stair clearance");ok(eng.pos.equals(new BlockPos(1,12,0))&&!eng.place,"top headroom removed before entering higher step");ok(eng.actionAt>400,"mining has a timed action instead of instant deletion");w.now=425;ok(Field28.mutate(n,eng,425)&&w.broken==1,"permitted common block can be mined with real drops");ok(w.getBlockState(new BlockPos(1,10,0)).id.equals("minecraft:stone"),"stair support retained");ok(Field28.plan(n,eng,440)&&eng.pos.equals(new BlockPos(1,11,0)),"second stair action clears remaining foot clearance");ok(Field28.mutate(n,eng,465),"second clearance actually opens stair");eng.pos=null;ok(Field28.plan(n,eng,480)&&eng.walkUntil==520,"finished two-block clearance becomes a native walkable upward step");eng.pos=new BlockPos(1,12,0);eng.block="minecraft:stone";w.blocks.put(new BlockPos(1,12,0),"minecraft:stone");int broken=w.broken;EventHooks.destroy=false;ok(!Field28.mutate(n,eng,426)&&w.broken==broken,"protection event veto prevents excavation");EventHooks.destroy=true;w.storage.put((BlockPos)eng.pos,new Object());ok(!Field28.mineable(n,eng.pos),"block entities and inventories never excavated");w.storage.clear();w.blocks.put((BlockPos)eng.pos,"minecraft:bedrock");ok(!Field28.mineable(n,eng.pos),"unbreakable or non-whitelisted terrain rejected");w.blocks.put((BlockPos)eng.pos,"minecraft:stone");w.loaded=false;ok(!Field28.mineable(n,eng.pos),"no loading chunks to break blocks");w.loaded=true;
 eng.pos=new BlockPos(1,10,1);eng.place=true;eng.block="minecraft:cobblestone";ok(!Field28.mutate(n,eng,430),"construction requires an actual inventory block");n.bag.add(new ItemStack("minecraft:cobblestone",2));EventHooks.placeCancelled=true;ok(!Field28.mutate(n,eng,431)&&w.getBlockState(eng.pos).isAir(),"cancelled placement restores old block snapshot");ok(n.bag.get(0).count==2,"cancelled placement never consumes material");EventHooks.placeCancelled=false;ok(Field28.mutate(n,eng,432)&&n.bag.get(0).count==1,"successful construction consumes exactly one inventory block");eng.pos=new BlockPos(1,10,2);ok(!Field28.mutate(n,eng,432)&&w.getBlockState(eng.pos).isAir(),"world-wide mutation budget allows one change per tick");w.unobstructed=false;ok(!Field28.mutate(n,eng,433),"placement cannot intersect an entity");w.unobstructed=true;EventHooks.grief=false;ok(!Field28.mutate(n,eng,434),"mob griefing veto applies to placement");EventHooks.grief=true;eng.window=400;eng.actions=6;ok(!Field28.allowedBudget(eng,500)&&Field28.allowedBudget(eng,1000),"six edits per thirty seconds caps escape damage");
 // Exercise the post-native tick action path, including animation/progress and navigation.
 var n2=npc(w);CalmBrain.state(n2).target=target;var action=Field28.state(n2);action.initialized=true;action.pos=new BlockPos(1,12,0);action.block="minecraft:stone";action.actionStart=500;action.actionAt=525;action.destination=new double[]{1.5,11,.5};w.now=510;ok(Field28.tick(n2)&&w.progress>=0,"native tick holds position and publishes block-breaking progress");w.now=525;ok(Field28.tick(n2)&&action.pos==null&&n2.jump.count==1,"completed action resumes navigation with a native jump");ok(w.progress==-1,"mining crack overlay cleared at completion");
 var trap=new World();var stuck=npc(trap);var enemy=new TacticsChecks24.Target(trap);enemy.x=6;enemy.y=13;CalmBrain.state(stuck).target=enemy;for(int y=10;y<=12;y++)trap.blocks.put(new BlockPos(1,y,0),"minecraft:stone");trap.now=600;ok(!Field28.tick(stuck),"first tick samples position without immediately modifying terrain");trap.now=620;ok(!Field28.tick(stuck),"brief navigation pause is not classified as stuck");trap.now=650;Sense28.state(stuck).end=655;ok(!Field28.tick(stuck)&&Field28.state(stuck).pos==null,"deliberate corner pause must never be mistaken for a digging blockage");Sense28.state(stuck).end=0;trap.now=710;ok(Field28.tick(stuck)&&Field28.state(stuck).pos!=null,"three-second stalled post-native tick activates escape planning");stuck.water=true;ok(!Field28.tick(stuck)&&!Field28.working(stuck),"falling into water cancels excavation and restores ordinary AI");
 System.out.println("HEARING_CORNERS_ESCAPE_MINING_BUILDING_PROTECTION_CHECKS="+checks);
 }
